raw:
{
  "spells": [
    {
      "id": "spell_water_01",
      "theory": "凝露术引导魔力贴近冷物表面，使空气中的水汽在杯壁、石面或金属片上聚成细珠。魔力只降低接触面的局部温度，水珠来自周围空气，因此干燥天气出露缓慢，潮湿的河谷清晨则较快。凝聚的水量有限，仅够润唇或浸湿一小块布，不能形成可饮用的水流。",
      "casting": "双手虚握杯壁两侧，食指沿杯口画半弧，低声念出短促水音，同时将魔力从掌心压向杯壁。若杯壁已经湿润，可省去画弧，直接以指节轻叩三下。",
      "failure": "魔力散逸时杯壁只泛起一层白雾，迟迟不结成水珠。若用力过猛，薄杯可能因局部温差出现细裂纹，水珠沿裂纹渗出，弄湿桌面或手掌。",
      "counters": [
        "用干布擦过杯壁并扇风，使水汽来不及聚集。",
        "将杯子移到通风处或火堆旁，温差不足便凝不出水。"
      ],
      "socialConsequences": "河谷旅人常以此润湿干裂的嘴唇，或为发烧的孩子取几滴凉水。陶匠担心骤冷骤热使薄胎杯开裂，会提醒客人先用温水涮杯。集市上有人用凝露术展示杯壁挂珠，引来围观，但摊主若见水珠滴落货品，会要求赔偿浸湿的布匹或纸张。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常凝出零星几点，杯壁干湿不均。",
        "熟练后水珠均匀附在杯壁，不再顺流而下。",
        "控制精准时可只凝湿杯口一圈，杯身保持干燥。",
        "极高熟练者能在薄石片上凝出细密水膜，水量仍不增加。"
      ]
    },
    {
      "id": "spell_water_02",
      "theory": "净水术将魔力送入水桶内部，像细网一样兜住悬浮的泥沙、草屑与浮沫，使它们沉向桶底或聚成团块浮起。魔力只处理看得见的杂质，溶解的盐分、看不见的毒物和契约痕迹都留在水中。处理后的水仍需煮沸或由有经验的人判断才能入口。",
      "casting": "单手按在桶沿，另一手在水中缓慢搅动三圈，每圈对应一次魔力推送。搅动时手掌须保持在水面以下，若桶太深可用长柄勺代替手指，但勺柄必须干燥。",
      "failure": "魔力推送不均匀时，杂质只在桶中央聚成一小团，其余部分依旧浑浊。若搅动过快，沉底的泥沙会被重新卷起，整桶水比处理前更浑，只能静置许久再取上层清水。",
      "counters": [
        "往水中撒一把细沙，使杂质附着沙粒加速沉降，打乱魔力网。",
        "用明矾或木炭先吸附污物，净水术便无物可聚。"
      ],
      "socialConsequences": "河谷村落常请会此术的人为公共水缸除泥，报酬是几块干饼或一捆柴。卖炭和卖明矾的商贩乐见人们仍需要传统净水材料，但若净水术者宣称能替代所有净水手段，他们会当众用浑水试验拆穿。港务人员对船上饮水处理有记录，若处理后仍有异味导致船员染病，会追究处理者的责任。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常漏掉桶底角落，水面仍漂着碎屑。",
        "熟练后杂质聚成团块，可用勺一次舀出。",
        "控制精准时能只除浮沫，不搅动底层沉淀。",
        "极高熟练者处理一桶水只需两圈搅动，沉渣更紧实。"
      ]
    },
    {
      "id": "spell_water_03",
      "theory": "辨泉术把极细的魔力丝探入近处水体，借水为媒传回盐分、腐败与铁锈的粗略气味。魔力丝只沿连续的水面或湿土延伸，遇到干燥石壁、木桶接缝或契约封蜡便无法穿过。它分辨的是水中可溶物的气味特征，不能读出隐藏的约定、印记或毒物名称，也不能判断水是否安全饮用。",
      "casting": "蹲在岸边或井沿，将食指与中指并拢浸入水中，闭眼静候三次呼吸。若水太浅，可将湿布铺在指上再按向水面，但布必须取自现场并完全浸湿。",
      "failure": "魔力丝中途散开时，脑中只留下模糊的潮湿感，无法分辨咸淡。若手指在水中移动过多，回传的气味会混入搅起的泥腥，让人误判水源已被污染，引起不必要的取水恐慌。",
      "counters": [
        "在水面撒一层油膜，魔力丝难以沿水面展开。",
        "用干沙或木炭隔开湿土，切断魔力丝延伸的路径。"
      ],
      "socialConsequences": "牧人依靠此术在河谷寻找含盐较低的浅泉，避免牲畜饮后生病。盐商不喜欢它，因为辨泉术者常当众指出某处泉水偏咸，影响附近盐井的销路。城镇公会要求以此术为公共水井作判断时须记录在案，若误报导致整街弃用一口好井，会追究判断者的责任。港务人员用它初查船舱积水是否混入海水，但最终货损认定仍需人工取样。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常把泥腥误作腐败，需要反复试探。",
        "熟练后能区分咸水与淡水的粗略差别。",
        "控制精准时可只探水面下浅层，不搅动沉泥。",
        "极高熟练者能沿湿土短距追踪，仍无法穿透干石与封蜡。"
      ]
    }
  ]
}
